-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 20
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 20 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 20', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 20 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-20.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é rastreabilidade no projeto do banco.', 0.2, 'Rastreabilidade é ligar cada **tabela**, coluna importante e **regra** do banco a um **requisito** do escopo do cliente, para saber por que cada coisa existe e se todo pedido foi atendido.', 'Nota cheia (0,2): ligação banco ↔ requisito do escopo. Metade (0,1): ideia incompleta (ex.: "conferir o banco" sem citar o requisito). Zero (0): sem relação.'),
      (v_atividade, 1, 2, 'Diga onde cada um dos requisitos R2, R3 e R6 está atendido no banco (tabela, restrição, procedimento ou permissão).', 0.4, 'R2 = **UNIQUE (id_aluno, id_turma)** na tabela matricula; R3 = procedimento **matricular**, que conta as matrículas ativas (com FOR UPDATE) e barra a 26ª; R6 = **GRANT SELECT (id_aluno, nome) ON aluno** para o grupo do financeiro (permissão por coluna), sem SELECT no CPF.', 'Nota cheia (0,4): os três certos. Metade (0,2): dois certos. Zero (0): um ou nenhum.'),
      (v_atividade, 1, 3, 'Explique o que indicam, na conferência, uma tabela que não atende a nenhum requisito e um requisito sem nada no banco.', 0.4, 'Tabela sem requisito **sobra** no modelo: precisa ser justificada ou retirada. Requisito sem tabela, restrição ou procedimento **falta**: o banco ainda não atende ao cliente e precisa ser completado.', 'Nota cheia (0,4): sobra e falta, com o que fazer em cada caso. Metade (0,2): só um dos casos. Zero (0): sem relação.'),
      (v_atividade, 2, 1, 'Explique por que os scripts precisam rodar numa ordem, com um exemplo de dependência.', 0.2, 'Porque um objeto **depende** de outro: turma precisa de curso (chave estrangeira), o trigger precisa da função, o GRANT precisa da tabela já criada. Fora da ordem, o script dá erro.', 'Nota cheia (0,2): dependência + exemplo correto. Metade (0,1): só a dependência sem exemplo, ou exemplo sem explicar. Zero (0): sem relação.'),
      (v_atividade, 2, 2, 'Escreva o 00-instalar.sql que chama os scripts 01 a 07 na ordem certa e para no primeiro erro, e o comando psql que o executa.', 0.4, '`\set ON_ERROR_STOP on`, depois `\i 01-ddl-escola.sql`, `\i 02-dados-teste.sql`, `\i 03-consultas-basicas.sql`, `\i 04-relatorios.sql`, `\i 05-procedimentos.sql`, `\i 06-triggers.sql`, `\i 07-seguranca.sql` (aceitar `\ir` e `\echo` entre eles). Execução: `psql -U postgres -d escola_teste -f sql/00-instalar.sql` (aceitar outro banco de teste).', 'Nota cheia (0,4): ON_ERROR_STOP + os 7 scripts na ordem + comando psql -f. Metade (0,2): scripts na ordem sem ON_ERROR_STOP ou sem o comando de execução. Zero (0): ordem errada ou sem \i.'),
      (v_atividade, 2, 3, 'Explique o que acontece se o script mestre não tiver \set ON_ERROR_STOP on e um dos scripts der erro.', 0.4, 'O psql **mostra o erro e continua** executando os outros scripts; o banco fica **pela metade** (falta tabela, função ou permissão) e o erro passa despercebido no meio das mensagens.', 'Nota cheia (0,4): continua + banco incompleto/erro escondido. Metade (0,2): só um dos dois. Zero (0): diz que o psql para ou desfaz tudo.'),
      (v_atividade, 3, 1, 'Explique por que o teste da instalação deve ser feito num banco limpo e em qual banco ele nunca deve ser feito.', 0.2, 'O banco de desenvolvimento pode ter objetos **criados à mão** que não estão nos scripts; só um banco **limpo** prova que os scripts sozinhos instalam tudo. Nunca testar no banco de **produção** (dados reais da escola).', 'Nota cheia (0,2): motivo + produção. Metade (0,1): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 3, 2, 'Escreva os comandos que criam um banco limpo escola_teste e instalam o projeto nele com o script mestre.', 0.4, '`DROP DATABASE IF EXISTS escola_teste;` e `CREATE DATABASE escola_teste;` (no psql ou com dropdb/createdb), depois `psql -U postgres -d escola_teste -f sql/00-instalar.sql`.', 'Nota cheia (0,4): criar o banco limpo + rodar o mestre nele. Metade (0,2): só um dos dois. Zero (0): roda no banco de produção ou comandos sem relação.'),
      (v_atividade, 3, 3, 'Diga como corrigir os dois erros do contexto (o da função e o do procedimento) para os scripts rodarem do zero e também uma segunda vez.', 0.4, '(1) A função **registrar_historico_nota** existia só no banco de desenvolvimento: colocar o **CREATE OR REPLACE FUNCTION** dela no script 06, **antes** do CREATE TRIGGER (e usar `DROP TRIGGER IF EXISTS ... ON matricula` antes do CREATE TRIGGER). (2) Trocar `CREATE PROCEDURE` por **CREATE OR REPLACE PROCEDURE matricular** no script 05, para rodar de novo sem o erro "já existe".', 'Nota cheia (0,4): as duas correções. Metade (0,2): uma correção. Zero (0): sem relação ou "apagar o banco toda vez".'),
      (v_atividade, 4, 1, 'Explique para que serve a documentação técnica do banco.', 0.2, 'Deixar **outra pessoa** (colega do back-end, professor, próxima equipe) **entender, instalar e usar** o banco sem precisar perguntar para quem fez.', 'Nota cheia (0,2): outra pessoa + entender/instalar/usar. Metade (0,1): ideia incompleta. Zero (0): "para ter mais páginas" ou sem relação.'),
      (v_atividade, 4, 2, 'Liste o que o README e o escopo atualizado precisam ter para outra pessoa instalar e entender o banco.', 0.4, 'README: **versão do PostgreSQL**, como **criar o banco**, o **comando do script mestre**, os **logins** que precisam existir (sem as senhas) e **como testar**. Escopo atualizado: **objetivo** do sistema, **requisitos**, o que **entra**, o que **não entra** e as **mudanças de escopo** aceitas durante o projeto.', 'Nota cheia (0,4): pelo menos 4 itens do README + 4 do escopo. Metade (0,2): só um dos documentos completo, ou os dois incompletos. Zero (0): sem relação ou com senha no README.'),
      (v_atividade, 4, 3, 'Escreva a linha do dicionário de dados da coluna valor da tabela parcela, com todos os campos que o dicionário pede.', 0.4, 'Exemplo: coluna **valor** · tipo **numeric(10,2)** · **não nula** (NOT NULL) · não é chave · regra **CHECK (valor > 0)** e não muda depois de paga (trigger) · exemplo **350.00**.', 'Nota cheia (0,4): nome, tipo, nulo, chave, regra e exemplo. Metade (0,2): três ou quatro desses campos. Zero (0): só o nome.'),
      (v_atividade, 5, 1, 'Diga quais colunas o cronograma da entrega final precisa ter.', 0.2, '**Tarefa**, **responsável**, data **prevista**, data **realizada** e **observação** (motivo dos atrasos).', 'Nota cheia (0,2): previsto + realizado + responsável. Metade (0,1): só o previsto ou sem responsável. Zero (0): sem relação.'),
      (v_atividade, 5, 2, 'Escreva a linha do cronograma da tarefa dos procedimentos com o previsto, o realizado e a observação.', 0.4, '| Procedimentos (05) | responsável (ex.: Bruno) | Aula 17 | Aula 18 | Atraso: a regra de vagas mudou (mudança de escopo aceita) |', 'Nota cheia (0,4): previsto 17 + realizado 18 + motivo. Metade (0,2): sem o motivo, ou trocando previsto e realizado. Zero (0): esconde o atraso (realizado igual ao previsto).'),
      (v_atividade, 5, 3, 'Diga qual recurso do banco executa cada uma das duas decisões do fluxograma e explique por que ligar o fluxograma ao banco melhora a documentação.', 0.4, '"Aluno já matriculado na turma?" = **UNIQUE (id_aluno, id_turma)** da tabela matricula; "Há vagas?" = procedimento **matricular** (conta as matrículas ativas e barra acima de 25). Ligar o fluxograma ao banco mostra **onde cada regra é executada**: o desenho deixa de ser só ilustração e vira a **explicação das regras** do banco, conferível no código.', 'Nota cheia (0,4): os dois recursos + o motivo. Metade (0,2): os dois recursos sem o motivo, ou um recurso com o motivo. Zero (0): recursos trocados.'),
      (v_atividade, 6, 1, 'Cite dois itens do checklist do modelo que conferem o DER com o banco.', 0.2, 'Dois entre: toda entidade virou tabela e toda tabela está no DER; toda tabela tem **chave primária**; toda ligação 1:N tem a **chave estrangeira** do lado N; N:N virou **tabela associativa**; o DER bate com o `\d` de cada tabela.', 'Nota cheia (0,2): dois itens certos. Metade (0,1): um item. Zero (0): nenhum.'),
      (v_atividade, 6, 2, 'Diga qual regra cada um dos três problemas do contexto fere (forma normal ou padrão de nomes).', 0.4, 'nome_curso em turma = **3FN** (depende do curso, não da chave da turma — dependência transitiva); telefones com lista = **1FN** (valor não atômico); IdMatrícula = **padrão de nomes** da UC (minúsculas, sem acento, id_ no início).', 'Nota cheia (0,4): os três certos. Metade (0,2): dois certos. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 3, 'Explique como corrigir cada um dos três problemas.', 0.4, 'Tirar **nome_curso** da turma e buscar o nome pelo JOIN com curso (id_curso); separar os telefones numa **tabela própria** (ex.: telefone_aluno com id_aluno) ou em colunas definidas com um telefone por coluna; renomear para **id_matricula** (`ALTER TABLE matricula RENAME COLUMN ...`).', 'Nota cheia (0,4): as três correções. Metade (0,2): duas correções. Zero (0): uma ou nenhuma.'),
      (v_atividade, 7, 1, 'Explique por que cada consulta do script deve ter um comentário dizendo qual tela ou relatório a usa.', 0.2, 'Para mostrar o **uso** de cada consulta no sistema (rastreabilidade): o colega do back-end sabe qual usar em cada tela, e consulta que **ninguém usa** sai do script.', 'Nota cheia (0,2): uso no sistema/tela + retirar o que não é usado ou orientar o back-end. Metade (0,1): ideia incompleta. Zero (0): sem relação.'),
      (v_atividade, 7, 2, 'Escreva a consulta das parcelas vencidas e não pagas, com o nome do aluno, para a tela de cobrança.', 0.4, '`SELECT a.nome, p.id_matricula, p.numero, p.vencimento, p.valor FROM parcela p JOIN matricula m ON m.id_matricula = p.id_matricula JOIN aluno a ON a.id_aluno = m.id_aluno WHERE p.vencimento < current_date AND p.data_pagamento IS NULL ORDER BY p.vencimento;`', 'Nota cheia (0,4): JOIN parcela-matricula-aluno + vencimento < current_date + data_pagamento IS NULL. Metade (0,2): uma das condições faltando ou sem o nome do aluno. Zero (0): condição invertida ou sem JOIN.'),
      (v_atividade, 7, 3, 'Escreva a consulta das turmas sem nenhuma matrícula para o painel da coordenação e explique o recurso que encontra essas turmas.', 0.4, '`SELECT t.codigo FROM turma t LEFT JOIN matricula m ON m.id_turma = t.id_turma WHERE m.id_matricula IS NULL;` (aceitar NOT EXISTS). O **LEFT JOIN** mantém todas as turmas; as que não têm matrícula ficam com as colunas de matricula **nulas**, e o IS NULL filtra essas.', 'Nota cheia (0,4): consulta certa + explicação do LEFT JOIN/IS NULL (ou NOT EXISTS). Metade (0,2): consulta certa sem explicação, ou explicação certa com erro pequeno no SQL. Zero (0): INNER JOIN ou sem relação.'),
      (v_atividade, 8, 1, 'Explique o que é o contrato com o back-end e por que o pedido do programador deve ser recusado.', 0.2, 'O contrato é a **lista do que a aplicação pode chamar** no banco (visões, procedimentos, comandos) e **com quais permissões**, pelo login **app_escola**. A senha do postgres não é entregue porque o postgres **pode tudo** (apagar o banco, criar papéis): fere o **menor privilégio**.', 'Nota cheia (0,2): lista do que pode chamar + motivo da recusa. Metade (0,1): só um dos dois. Zero (0): aceita entregar o postgres.'),
      (v_atividade, 8, 2, 'Escreva os GRANT do app_escola para matricular, registrar pagamento e editar só nome, e-mail e telefone do aluno.', 0.4, '`GRANT CONNECT ON DATABASE escola_db TO app_escola; GRANT USAGE ON SCHEMA public TO app_escola; GRANT EXECUTE ON PROCEDURE matricular(integer, integer) TO app_escola; GRANT EXECUTE ON PROCEDURE registrar_pagamento(integer, smallint) TO app_escola; GRANT SELECT, UPDATE (nome, email, telefone) ON aluno TO app_escola;` (aceitar SELECT nas colunas que a tela mostra).', 'Nota cheia (0,4): EXECUTE nos dois procedimentos + UPDATE só nas três colunas. Metade (0,2): falta um procedimento ou UPDATE na tabela inteira. Zero (0): GRANT ALL ou DELETE.'),
      (v_atividade, 8, 3, 'Explique por que o back-end deve usar consultas com parâmetros e onde deve ficar a senha do app_escola.', 0.4, 'Consultas com **parâmetros** ($1, $2) impedem o **SQL injection**: o texto digitado pelo usuário nunca vira comando. A senha do app_escola fica numa **variável de ambiente** do servidor, **nunca no Git** nem no JavaScript do site.', 'Nota cheia (0,4): SQL injection + variável de ambiente fora do Git. Metade (0,2): só um dos dois. Zero (0): senha no README ou no código.'),
      (v_atividade, 9, 1, 'Cite os comandos do psql que conferem, depois da instalação, as tabelas, as visões, as funções e procedimentos e os papéis.', 0.2, '**\dt** (tabelas), **\dv** (visões), **\df** (funções e procedimentos) e **\du** (papéis).', 'Nota cheia (0,2): os quatro. Metade (0,1): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 9, 2, 'Escreva dois testes do roteiro com o resultado esperado: uma matrícula repetida e o login do financeiro tentando ver o CPF.', 0.4, '(1) Repetir `CALL matricular(1, 2);` → **erro** do UNIQUE (id_aluno, id_turma) (matrícula duplicada), mostrando que a regra R2 funciona. (2) No login do financeiro, `SELECT cpf FROM aluno;` → **ERROR: permission denied**, mostrando que a matriz de acesso (R6) foi respeitada.', 'Nota cheia (0,4): os dois testes com o resultado esperado. Metade (0,2): um teste completo, ou os dois sem o resultado. Zero (0): resultados trocados (aceitar a matrícula repetida ou mostrar o CPF).'),
      (v_atividade, 9, 3, 'Escreva o comando do backup de entrega e os comandos que provam que ele funciona, e explique por que essa prova é necessária.', 0.4, 'Backup: `pg_dump -U postgres -d escola_teste -F c -f escola.dump`. Prova: `createdb escola_restaurado` e `pg_restore -d escola_restaurado escola.dump`, conferindo as tabelas e os dados. Backup que **nunca foi restaurado** não é garantia de **disponibilidade**: só a restauração prova que o arquivo serve.', 'Nota cheia (0,4): pg_dump + pg_restore num banco novo + motivo. Metade (0,2): pg_dump sem a restauração, ou restauração sem o motivo. Zero (0): sem relação.'),
      (v_atividade, 10, 1, 'Diga como a revisão cruzada testa o projeto de outra equipe.', 0.2, 'A equipe revisora segue **só o README** e roda o **script mestre num banco limpo**, preenchendo a ficha (instalação, teste de ponta a ponta, modelo, segurança e documentação). Toda dificuldade aponta uma falha da documentação.', 'Nota cheia (0,2): só pelo README + banco limpo/ficha. Metade (0,1): só um dos dois. Zero (0): sem relação.'),
      (v_atividade, 10, 2, 'Reescreva a sugestão no formato "o quê, onde, efeito" com um problema real de instalação e diga como a equipe deve receber a sugestão.', 0.4, 'Exemplo: "O **06-triggers.sql** (o quê/onde) cria o trigger antes da função registrar_historico_nota, e a instalação **para com erro no passo 6** (efeito)." A equipe **anota** a sugestão no registro, agradece, **decide** se aceita e **responde com o motivo** — crítica ao trabalho, nunca à pessoa.', 'Nota cheia (0,4): sugestão com o quê, onde e efeito + como receber. Metade (0,2): só uma das duas partes. Zero (0): crítica pessoal ou sem relação.'),
      (v_atividade, 10, 3, 'Escreva a linha do registro de decisões para "matrícula é cancelada, não apagada", com o motivo e a alternativa descartada.', 0.4, '| Matrícula é cancelada, não apagada | Guardar o **histórico** e as parcelas, protegendo a **integridade** (requisito de saber quem alterou e de manter os pagamentos) | DELETE com ON DELETE CASCADE |', 'Nota cheia (0,4): decisão + motivo ligado ao requisito/integridade + alternativa descartada. Metade (0,2): falta o motivo ou a alternativa. Zero (0): sem relação.');
end $$;
